import urllib.request
import xml.etree.ElementTree as ET
import json
import os
import time
import random

BASE = os.path.expanduser('~/Projects/provenance/test_suite')

# ============ 1. ACADEMIC PAPERS (20) from arXiv ============
print('=== Fetching 20 academic abstracts from arXiv ===')
academic_queries = [
    'http://export.arxiv.org/api/query?search_query=cat:cs.AI&start=0&max_results=5&sortBy=submittedDate&sortOrder=ascending',
    'http://export.arxiv.org/api/query?search_query=cat:physics.gen-ph&start=0&max_results=5&sortBy=submittedDate&sortOrder=ascending',
    'http://export.arxiv.org/api/query?search_query=cat:math.CO&start=0&max_results=5&sortBy=submittedDate&sortOrder=ascending',
    'http://export.arxiv.org/api/query?search_query=cat:q-bio.NC&start=0&max_results=5&sortBy=submittedDate&sortOrder=ascending',
]
ns = {'atom': 'http://www.w3.org/2005/Atom'}
count = 0
for url in academic_queries:
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        resp = urllib.request.urlopen(req, timeout=15)
        root = ET.fromstring(resp.read())
        for entry in root.findall('atom:entry', ns):
            title = entry.find('atom:title', ns).text.strip().replace('\n', ' ')
            abstract = entry.find('atom:summary', ns).text.strip().replace('\n', ' ')
            if len(abstract) > 200:
                count += 1
                fname = f'{BASE}/academic/academic_{count:03d}.txt'
                with open(fname, 'w') as f:
                    f.write(f'{title}\n\n{abstract}')
                print(f'  academic_{count:03d}: {title[:60]}...')
        time.sleep(1)
    except Exception as e:
        print(f'  Error: {e}')
print(f'Got {count} academic papers')

