# ============ MANIFEST ============
print('\n=== Creating manifest ===')
manifest = {'total': 0, 'categories': {}}
for cat in ['academic', 'literary', 'legal', 'journalism', 'technical', 'personal', 'business', 'medical', 'political', 'mixed']:
    path = f'{BASE}/{cat}'
    files = sorted([f for f in os.listdir(path) if f.endswith('.txt')])
    manifest['categories'][cat] = {'count': len(files), 'files': files}
    manifest['total'] += len(files)

with open(f'{BASE}/manifest.json', 'w') as f:
    json.dump(manifest, f, indent=2)

print(f'\n=== TOTAL: {manifest["total"]} test documents created ===')
for cat, info in manifest['categories'].items():
    print(f'  {cat}: {info["count"]}')
